import type { TraceViewOptions } from "@declarative-agents/ui-kit";
import declared from "./declaredDescriptions.json";

// What the kit's trace views need from this application (srd004 R4): the
// one-line description each declared word carries, regenerated by mage
// ui:machines, and the tool a forced call invokes. The kit renders the trace;
// which words exist and what they claim is this mesh's own declaration.
const DESCRIPTIONS = (declared as { descriptions: Record<string, string> }).descriptions;

// The declared tool each forced-call op invokes (GH-710): the follow-on row
// names the tool the model called, the way a Cohere tool-use reply reads.
const FORCED_TOOL_NAMES: Record<string, string> = {
  select_sources_via_tool: "select_sources",
  derive_search_terms_via_tool: "report_search_terms",
  translate_segments_via_tool: "deliver_translations",
};

export const traceOptions: TraceViewOptions = {
  describe: (command) => DESCRIPTIONS[command],
  toolNames: FORCED_TOOL_NAMES,
};
